create extension if not exists pgcrypto; create type public.platform as enum ('whatsapp','instagram'); create type public.message_direction as enum ('inbound','outbound');
create table public.user_settings(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,system_prompt text not null default 'You are my personal AI messaging assistant.',automation_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contacts(id uuid primary key default gen_random_uuid(),platform public.platform not null,external_contact_id text not null,display_name text,created_at timestamptz not null default now(),unique(platform,external_contact_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),contact_id uuid not null references public.contacts(id) on delete cascade,platform public.platform not null,bot_enabled boolean not null default true,escalated boolean not null default false,last_message_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,direction public.message_direction not null,content text not null,external_message_id text,created_at timestamptz not null default now(),unique(external_message_id));
create table public.webhook_events(id uuid primary key default gen_random_uuid(),external_event_id text unique not null,platform public.platform not null,payload jsonb not null,status text not null default 'accepted',created_at timestamptz not null default now());
create table public.safety_decisions(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,classification text not null,reason text,action text not null,created_at timestamptz not null default now());
create index conversations_last_message_idx on public.conversations(last_message_at desc); create index messages_conversation_created_idx on public.messages(conversation_id,created_at desc);
alter table public.user_settings enable row level security; alter table public.contacts enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.webhook_events enable row level security; alter table public.safety_decisions enable row level security;
revoke all on all tables in schema public from anon,authenticated; grant select,insert,update,delete on public.user_settings,public.contacts,public.conversations,public.messages,public.safety_decisions to authenticated;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_settings where user_id=auth.uid())$$;
create policy owner_settings on public.user_settings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy owner_contacts on public.contacts for all to authenticated using(public.is_owner()) with check(public.is_owner()); create policy owner_conversations on public.conversations for all to authenticated using(public.is_owner()) with check(public.is_owner()); create policy owner_messages on public.messages for all to authenticated using(public.is_owner()) with check(public.is_owner()); create policy owner_safety on public.safety_decisions for all to authenticated using(public.is_owner()) with check(public.is_owner());
